import java.util.*;

public class Main {
    static String classify(String method, int status) {
        if (status >= 200 && status < 300) return "SUCCESS";
        boolean safe = method.equals("GET") || method.equals("PUT") || method.equals("DELETE");
        boolean transientFailure = status == 429 || status == 502 || status == 503 || status == 504;
        return safe && transientFailure ? "RETRY" : "FAIL";
    }

    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        System.out.println(classify(sc.next(), sc.nextInt()));
    }
}

