import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String method = sc.next();
        int maxAttempts = sc.nextInt(), baseMs = sc.nextInt();
        Set<Integer> retryable = Set.of(429, 502, 503, 504);
        boolean idempotent = Set.of("GET", "PUT", "DELETE").contains(method);
        for (int k = 1; k <= maxAttempts; k++) {
            int status = sc.nextInt();
            if (status / 100 == 2) {
                System.out.println(k + " SUCCESS " + status);
                System.out.println("RESULT OK " + k);
                return;
            }
            if (idempotent && retryable.contains(status)) {
                System.out.println(k < maxAttempts ? k + " RETRY " + status + " wait=" + baseMs * (1L << (k - 1)) : k + " RETRY " + status);
                continue;
            }
            System.out.println(k + " FAIL " + status);
            System.out.println("RESULT FAILED " + k);
            return;
        }
        System.out.println("RESULT GIVEUP " + maxAttempts);
    }
}

